sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_autop;
uniform float amzp_autoSpeed;
uniform float amzp_progress;
uniform float amzp_amount;
uniform float amzp_gfps;
uniform float amzp_chance;
uniform float amzp_seed;
uniform float amzp_slices;
uniform float amzp_sliceH;
uniform float amzp_shift;
uniform float amzp_sliceRgb;
uniform float amzp_splitMode;
uniform float amzp_split;
uniform float amzp_splitAngle;
uniform float amzp_splitKeep;
uniform float amzp_blocks;
uniform float2 amzp_blockSize;
uniform float amzp_blockShift;
uniform float amzp_channelSwap;
uniform float amzp_noise;
uniform float amzp_scan;
uniform float amzp_scanSize;
uniform float amzp_flicker;
uniform float amzp_advScale;
uniform float amzp_advAngle;
uniform float amzp_mixAmt;
uniform float amzp_overdrawOn;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float2 rot2(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float h1(float x) { return fract(sin(x * 91.3458 + amzp_seed * 17.13) * 47453.5453); }
    float h2(float2 p) { return fract(sin(dot(p, float2(127.1, 311.7)) + amzp_seed * 3.917) * 43758.5453); }
    float tm() { return (amzp_autop>0.5) ? amzp_progress + time * amzp_autoSpeed : amzp_progress; }
    float4 at(float2 s) {
        if (!(amzp_overdrawOn>0.5)) s = 1.0 - abs(mod(s, 2.0) - 1.0);
        return amzTexture(0, l2s(s));
    }
    float4 splitAt(float2 s, float2 d) {
        float4 r = at(s + d), g = at(s), b = at(s - d);
        return float4(r.r, g.g, b.b, max(max(r.a, g.a), b.a));
    }
    void amzRender() {
        float2 W = layer;
        float2 uv = amzLayerNorm();
        float4 orig = amzTexture(0, amzScreenNorm());
        float t = tm();
        float frame = floor(t * max(amzp_gfps, 0.01));
        float on = step(h1(frame + 0.37), clamp(amzp_chance, 0.0, 1.0)) * clamp(amzp_amount, 0.0, 2.0);
        float k = max(amzp_advScale, 0.01);
        float aa = radians(amzp_advAngle);
        float2 gp = rot2((uv - 0.5) * W, -aa) / k;
        float hgt = W.y / k;
        float2 dirX = rot2(float2(1.0, 0.0), aa) / W;
        float2 s = uv;
        float inSlice = 0.0;
        for (int i = 0; i < 40; i++) {
            if (float(i) >= amzp_slices) break;
            float fi = float(i);
            float y0 = h1(frame * 1.31 + fi * 7.77) - 0.5;
            float hh = h1(frame * 2.17 + fi * 3.33) * amzp_sliceH;
            float y = gp.y / hgt;
            if (y > y0 && y < y0 + hh) {
                float off = (h1(frame * 5.03 + fi * 9.11) - 0.5) * 2.0 * amzp_shift * on;
                s += dirX * off * W.x;
                inSlice = 1.0;
            }
        }
        float2 bs = max(amzp_blockSize, float2(1.0));
        float2 cell = floor(gp / bs);
        float bh = h2(cell + frame * 0.731);
        float blk = step(bh, amzp_blocks * on);
        if (blk > 0.0) {
            float2 jump = (float2(h2(cell + 3.1 + frame), h2(cell + 7.7 + frame)) - 0.5) * 2.0 * amzp_blockShift;
            s += jump;
        }
        float sa = 0.0;
        if (int(amzp_splitMode) == 0) sa = h1(frame * 3.71) * 6.2831853;
        else if (int(amzp_splitMode) == 2) sa = 1.5707963;
        float2 d = rot2(float2(1.0, 0.0), sa + radians(amzp_splitAngle)) * W.y / W;
        if (int(amzp_splitMode) == 3) { float2 q = (uv - 0.5) * W; d = (length(q) > 0.0 ? normalize(q) : float2(0.0)) * W.y / W * min(length(q) / (0.5 * W.y), 2.0); }
        float sp = amzp_split * mix(clamp(amzp_splitKeep, 0.0, 1.0), 1.0, min(on, 1.0)) * max(on, 1.0);
        if ((amzp_sliceRgb>0.5) && inSlice > 0.0) sp += amzp_split * on;
        float4 c = splitAt(s, d * sp);
        if (blk > 0.0) {
            float cs = h2(cell + 11.3 + frame);
            float3 sw = cs < 0.33 ? c.gbr : (cs < 0.66 ? c.brg : c.rbg);
            c.rgb = mix(c.rgb, sw, clamp(amzp_channelSwap, 0.0, 1.0));
        }
        float g = (h2(floor(gp) + frame * 1.7) - 0.5) * amzp_noise * (0.4 + 0.6 * min(on, 1.0));
        c.rgb += g * c.a;
        float line = mod(floor(gp.y / max(amzp_scanSize, 1.0)), 2.0);
        c.rgb *= 1.0 - amzp_scan * 0.5 * line;
        c.rgb *= 1.0 + (h1(frame * 0.913) - 0.5) * 2.0 * amzp_flicker * min(on, 1.0);
        c.rgb = clamp(c.rgb, float3(0.0), float3(c.a));
        c = mix(orig, c, clamp(amzp_mixAmt, 0.0, 1.0));
        amzOutput = (amzp_overdrawOn>0.5) ? c : c * orig.a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
